#ifdef GL_ES
    precision mediump float;
#endif

varying vec2 v_texCoord;
uniform sampler2D u_texture;

// 挖洞中心和半径的数组
uniform vec2 u_holeCenters[3]; // 假设最多支持10个椭圆
uniform vec2 u_holeRadii[3];    // 椭圆半径数组
uniform int u_holeCount;          // 当前椭圆数量
uniform vec2 u_spriteSize;
uniform float u_opatity;          // 光圈以外的透明度（魔族透明度较高）

void main()
{
    vec4 color = texture2D(u_texture, v_texCoord);

    // 遍历所有椭圆
    for (int i = 0; i < u_holeCount; i++) {
        // 计算当前像素到挖洞中心的标准化坐标
        vec2 normalizedCoord = (v_texCoord - u_holeCenters[i]) * u_spriteSize / min(u_spriteSize.x, u_spriteSize.y);

        // 使用椭圆方程判断是否在挖洞范围内
        float ellipseEquation = (normalizedCoord.x * normalizedCoord.x) / (u_holeRadii[i].x * u_holeRadii[i].x) +
                                (normalizedCoord.y * normalizedCoord.y) / (u_holeRadii[i].y * u_holeRadii[i].y);

        // 如果在挖洞范围内，计算透明度
        if (ellipseEquation < 1.0) {
            float opacity = smoothstep(0.0, 1.0, ellipseEquation); 
            opacity = mix(0.0, u_opatity, opacity);
            color = vec4(0.0, 0.0, 0.0, opacity);
        }else{
            color = vec4(color.rgb, color.a * u_opatity); 
        }
    }
    gl_FragColor = color; 
}

#ifdef GL_ES
precision mediump float;
#endif

varying vec4 v_fragmentColor;
varying vec2 v_texCoord;

uniform vec4 u_frameRect;
uniform vec2 u_atlasSize;
uniform float u_isRotated;
uniform sampler2D u_mask_texture;
uniform vec2 sp_size;
uniform vec2 mask_size;
uniform vec2 v_offset;
uniform float u_enable;


// cocos4.0 参数名称变化 CC_Texture0 -> u_texture
uniform sampler2D u_texture;

void main() {
    // vec2 atlasCoord = vec2(u_frameRect.x + u_frameRect.z * v_texCoord.x, u_frameRect.y + u_frameRect.w * v_texCoord.y);
    vec2 texCoord = v_texCoord;
    vec2 pos = vec2(0.0, 0.0);
    if(u_isRotated != 0.0) {
        pos = vec2((texCoord.y-u_frameRect.y)*u_atlasSize.y, sp_size.x-(texCoord.x-u_frameRect.x)*u_atlasSize.x);
    }else{
        pos = vec2((texCoord.x-u_frameRect.x)*u_atlasSize.x, (texCoord.y-u_frameRect.y)*u_atlasSize.y);
    }

    vec2 offset = vec2(pos.x - v_offset.x, pos.y - v_offset.y);

    if(offset.x <= mask_size.x && offset.x >= 0.0 && offset.y <= mask_size.y && offset.y >= 0.0) 
    {
        vec2 finCoord = vec2(offset.x/mask_size.x, offset.y/mask_size.y);
        vec4 mask_FragColor = texture2D(u_mask_texture, finCoord);

        vec4 texColor = texture2D(u_texture, v_texCoord);
        gl_FragColor = v_fragmentColor*texColor;

        gl_FragColor.a = (1.0-mask_FragColor.a*u_enable) * texColor.a;
    }else{
        gl_FragColor = v_fragmentColor*texture2D(u_texture, v_texCoord);
    }
}

varying vec2 v_texCoord;


uniform vec3 u_color;
uniform vec3 u_tColor;
uniform float u_flash; // 控制闪烁的变量
uniform int u_isFlashing; // 使用整数控制是否闪烁的变量
uniform int u_isBorder; 
uniform float u_colorOffset; // 色值倍率

uniform vec3 allColor;
uniform sampler2D u_texture;

const int SAMPLES = 10;
varying vec2 v_OutlineSamples[SAMPLES];
void main() {
    // 获取当前纹理颜色
    vec4 textureColor = texture2D(u_texture, v_texCoord);

    vec4 newColor = vec4(textureColor.rgb, textureColor.a);

    //染色
    float originB = textureColor.b * u_colorOffset; // 色值倍率调整(强化等级修改倍率) 
    //修改备注：2100001防弹衣M 装备需g值包含0
    if (length(u_tColor) >= 0.0 && textureColor.b > 0.031 && textureColor.r == 0.0  && (textureColor.g >= 0.0 && textureColor.g < 0.031) && textureColor.a > 0.0)
    {
        newColor.r = u_tColor.r * originB;
        newColor.g = u_tColor.g * originB;
        newColor.b = u_tColor.b * originB;
    }

    //状态染色
    if ( length(allColor) > 0.0 && textureColor.a > 0.0){
        if (allColor.r == 0.5 && allColor.g == 0.5 && allColor.b == 0.5) 
        {
            float gray = (newColor.r + newColor.g + newColor.b) / 3.0;
            newColor.rgb = vec3(gray, gray, gray);
        }else{
            newColor.rgb = newColor.rgb * allColor.rgb;
        }
    }

    if (u_isBorder == 0){
        gl_FragColor = newColor; // 显示原始纹理颜色
    }else{
        // 计算边缘 alpha
        float edgeAlpha = 0.0;
        for (int i = 0; i < SAMPLES; i++) {
            vec4 sampleColor = texture2D(u_texture, v_OutlineSamples[i]);
            if (sampleColor.a > 0.0) {
                edgeAlpha = max(edgeAlpha, sampleColor.a); // 计算边缘的 alpha
            }
        }

        // 设置边缘颜色为金黄色
        vec4 outlineColor = vec4(u_color.r, u_color.g, u_color.b, edgeAlpha);

        // 计算闪烁颜色
        vec4 flashColor = mix(vec4(1.0, 1.0, 1.0, 1.0), vec4(0.0, 0.0, 1.0, 1.0), (sin(u_flash * 3.14) + 1.0) / 2.0); // 由白色到蓝色的渐变

        if(u_isFlashing==1){
            outlineColor = flashColor;
        }
        // 只有在透明色与颜色交汇处显示金黄色
        if (newColor.a == 0.0 && edgeAlpha > 0.0) {
            gl_FragColor = outlineColor; // 边缘部分显示金黄色
        } else if (newColor.a > 0.0) {
            gl_FragColor = newColor; // 显示原始纹理颜色
        } else {
            gl_FragColor = vec4(0.0, 0.0, 0.0, 0.0); // 透明部分
        }
    }


}

